deps = {'dashboard':['foundation'], 'context':['models'], 'memory':['foundation'], 'reports':['research'], 'daily-projects':['schedule','reports'], 'mouse':['observe','workflows'], 'visual-agent':['mouse','models'], 'autologin':['foundation','runtime'], 'phone':['voice','workflows'], 'sandbox':['roadmap'], 'flags':['workflows'], 'cloud':['backup'], 'installer':['runtime','backup']}
items=[]
for ident,title,phase,origin,status,difficulty,desc,next_step,owner in ROWS:
    items.append(dict(id=ident,title=title,phase=phase,origin=origin,status=status,difficulty=difficulty,description=desc,next_step=next_step,owner_action=owner,dependencies=deps.get(ident,[]),enabled=True,test_mode='isolated',test_result='not_run',notes='',priority='now' if ident in {'runtime','context','roadmap'} else 'next' if phase.startswith('5') else 'later',evidence='Source implementation and historical checklist; live acceptance is separate.' if status=='implemented' else ''))
(ROOT/'backend/assistant/roadmap_seed.json').write_text(json.dumps(items,indent=2)+'\n',encoding='utf-8')
doc=['# Derek — complete product roadmap','', 'Snapshot: 2026-10-24. This inventory consolidates the original plan and later requests. Implemented means code exists; verified requires recorded acceptance evidence. Historical checklist entries describe their date, not necessarily current configuration.','', '## How to use the live board','', 'Open **Roadmap** in Derek. Changes are owner-scoped and saved in the application database. The board starts from this catalog once; later catalog edits never overwrite your custom board. Use Save changes, then Export JSON for a portable copy or Copy prompt to hand a feature to Codex. Unsaved edits are marked. Stale saves are rejected.','', 'Planning enabled/disabled controls inclusion in generated prompts. Test mode and Queue test plan record intentions only. They do not run commands, activate features, or grant permissions. Verified/passed requires evidence. Runtime feature switches and an isolated execution runner are separate future blocks.','', 'Additional controls: search/status filters, dependency validation, priority selection, evidence/results tracking, duplicate blocks, archive-by-disabling, JSON export and printable visual roadmap. No automatic prompt execution. Do not put credentials in roadmap notes.','', '## Delivery order','', '1. Fix runtime health and accept existing model/channel controls.','2. Accept memory, scheduling and scoped browser/file flows.','3. Add secure desktop auto sign-in, observation, then reviewed mouse actions.','4. Add streaming, recovery drills and signed packaging.','5. Provision optional cloud/phone only after account, cost and transport decisions.','6. Evaluate extensions against real usage before committing.','', '## Inventory and actionable checklist','']
for i in items:
    doc += [f"### {i['title']} · {i['id']}",'',f"- Phase: {i['phase']} · Origin: {i['origin']}",f"- Status: **{i['status']}** · Difficulty: **{i['difficulty']}**",f"- Scope: {i['description']}",f"- [ ] Next acceptance/work: {i['next_step']}",f"- Your part: {i['owner_action']}",f"- Dependencies: {', '.join(i['dependencies']) or 'None specified'}",'']
doc += ['## Hardest parts and practical limits','', '- Desktop control: focus changes, inaccessible UI, elevated windows, DPI and nondeterministic pages require observation freshness and fail-closed action checks. Full arbitrary application coverage is not a realistic acceptance promise.','- Phone: a usable SIM alone does not expose call audio to a server; routing, gateway support, identity verification and latency remain unresolved.','- Local speed: model size, available RAM and CPU/GPU determine latency; a router does not make a slow underlying model faster.','- Always on: sign-in startup does not execute while the laptop is asleep or powered off. Cloud availability still needs deployment.','- Custom training: data quality, licensing, compute and regression evaluation make this a separate substantial project.','- Isolation and feature switches: planning metadata is intentionally not an execution permission. A real sandbox and server-enforced switches need their own implementation.','', '## Reference history','', '- [Implementation checklist](IMPLEMENTATION_CHECKLIST.md)','- [Earlier implementation history](IMPLEMENTATION_HISTORY.md)','- [Model and controls](MODEL_USAGE_AND_CONTROLS.md)','- [Data flow](DEREK_MODEL_AND_DATA_FLOW.md)','- [Screen control stages](SCREEN_CONTROL_PLAN.md)','- [Phone setup](PHONE_SETUP.md)','', '![Roadmap overview](docs/roadmap.svg)','']
(ROOT/'PRODUCT_ROADMAP.md').write_text('\n'.join(doc),encoding='utf-8')
(ROOT/'docs').mkdir(exist_ok=True)
phases=list(dict.fromkeys(i['phase'] for i in items))
svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="1040" viewBox="0 0 1280 1040">','<rect width="1280" height="1040" fill="#102b29"/>','<text x="50" y="65" fill="#eff7ef" font-family="sans-serif" font-size="34">DEREK / PRODUCT ROADMAP</text>','<text x="50" y="98" fill="#b7d1c8" font-family="sans-serif" font-size="17">October 24, 2026 • Code present ≠ live verified • Future items are proposals</text>']
for n,phase in enumerate(phases):
    x=50+(n%2)*610; y=135+(n//2)*220
    svg += [f'<rect x="{x}" y="{y}" width="580" height="200" rx="15" fill="#21453f"/>',f'<text x="{x+20}" y="{y+33}" fill="#c7ef9d" font-family="sans-serif" font-size="22">{escape(phase)}</text>']
    titles=[i['title'] for i in items if i['phase']==phase]
    for j,line in enumerate(titles[:6]):
        svg.append(f'<text x="{x+20}" y="{y+61+j*22}" fill="#eff7ef" font-family="sans-serif" font-size="15">{escape(line)}</text>')
    if len(titles)>6: svg.append(f'<text x="{x+20}" y="{y+190}" fill="#b7d1c8" font-family="sans-serif" font-size="13">+ {len(titles)-6} more blocks in the interactive roadmap</text>')
svg += ['<text x="50" y="1020" fill="#b7d1c8" font-family="sans-serif" font-size="16">Next: runtime acceptance → desktop access → recovery / release → optional cloud and phone</text>','</svg>']
(ROOT/'docs/roadmap.svg').write_text('\n'.join(svg),encoding='utf-8')

if __name__ == '__main__':
    print(f'Wrote {len(items)} roadmap blocks, PRODUCT_ROADMAP.md and docs/roadmap.svg')
